#!/usr/bin/env bash
# Kuro OS — Hyprland session, your side (no sudo). Run after 1500-hyprland-install.sh.
#   bash ~/bapirlo-os/1510-hyprland.sh            # link configs + colour them from Theme Studio
#   bash ~/bapirlo-os/1510-hyprland.sh restore    # put back whatever was in ~/.config before
#
# Links (edit these in ~/bapirlo-os/hypr, they are the source):
#   ~/.config/hypr/hyprland.lua (0.57+ Lua config), hyprland.conf (legacy), hypridle.conf   ~/.config/waybar/config.jsonc
# Generated by tools/hypr-theme.py (re-run by Theme Studio on every re-theme):
#   ~/.config/hypr/{bapirlo-colors,hyprlock}.conf, bapirlo-colors.lua   ~/.config/waybar/style.css
#   ~/.config/fuzzel/fuzzel.ini   ~/.config/mako/config
# Only affects the "Kuro Hyprland" login choice; GNOME never reads any of these.
set -euo pipefail
[ "$(id -u)" -ne 0 ] || { echo "Run as yourself, WITHOUT sudo."; exit 1; }
HERE=$(dirname "$(readlink -f "$0")")
LATEST=~/theme-backups/LATEST-HYPRLAND
FILES=(hypr/hyprland.lua hypr/hyprland.conf hypr/hypridle.conf hypr/bapirlo-colors.lua waybar/config.jsonc
       hypr/bapirlo-colors.conf hypr/hyprlock.conf waybar/style.css fuzzel/fuzzel.ini mako/config)

apply() {
  if [ -s "$LATEST" ] && [ -d "$(cat "$LATEST")" ]; then
    echo "re-run: keeping the first backup -> $(cat "$LATEST")"
  else
    local BK=~/theme-backups/$(date +%Y%m%d-%H%M%S)-hyprland
    mkdir -p "$BK"
    for f in "${FILES[@]}"; do
      [ -e ~/.config/"$f" ] && [ ! -L ~/.config/"$f" ] && { mkdir -p "$BK/$(dirname "$f")"; cp -a ~/.config/"$f" "$BK/$f"; }
    done
    echo "$BK" > "$LATEST"; echo "backup -> $BK"
  fi

  mkdir -p ~/.config/hypr ~/.config/waybar ~/Pictures/Screenshots
  ln -sfn "$HERE/hypr/hypr/hyprland.lua" ~/.config/hypr/hyprland.lua
  ln -sfn "$HERE/hypr/hypr/hyprland.conf" ~/.config/hypr/hyprland.conf
  ln -sfn "$HERE/hypr/hypr/hypridle.conf" ~/.config/hypr/hypridle.conf
  ln -sfn "$HERE/hypr/waybar/config.jsonc" ~/.config/waybar/config.jsonc
  "$HERE/tools/hypr-theme.py"
  echo "configs linked + coloured from Theme Studio"

  if command -v Hyprland >/dev/null; then
    echo; echo "== checking the config with Hyprland itself"
    Hyprland --verify-config -c ~/.config/hypr/hyprland.lua || echo "!! see the errors above"
  else
    echo "(Hyprland not installed yet — run 1500-hyprland-install.sh, then this again to check the config)"
  fi
  echo; echo "Log out → pick \"Kuro Hyprland\" at the login screen. Super+Space = apps, Super+Shift+E = power menu."
}

restore() {
  local BK; BK=$(cat "$LATEST" 2>/dev/null || true)
  [ -d "$BK" ] || { echo "no backup at $LATEST"; exit 1; }
  for f in "${FILES[@]}"; do
    rm -f ~/.config/"$f"
    [ -e "$BK/$f" ] && { mkdir -p ~/.config/"$(dirname "$f")"; cp -a "$BK/$f" ~/.config/"$f"; }
  done
  echo "restored ~/.config from $BK"
}

case "${1:-apply}" in
  apply) apply ;;
  restore) restore ;;
  *) echo "usage: $0 [restore]"; exit 1 ;;
esac
